<?php
namespace Dth\Crm\Filament\Resources\StaffResource\RelationManagers; use Filament\Resources\RelationManagers\RelationManager; use Filament\Schemas\Schema; use Filament\Tables\Table; use Filament\Tables\Columns\TextColumn; use Filament\Actions; use Filament\Forms\Components\{Select,Textarea,DatePicker};
class AvailabilitiesRelationManager extends RelationManager {protected static string $relationship='availabilities';public static function getTitle($o,string $p):string{return 'Lịch khả dụng';} public function form(Schema $s):Schema{return $s->components([DatePicker::make('date')->required(),Select::make('status')->options(\Dth\Crm\Enums\StaffAvailabilityStatus::options())->required(),Textarea::make('note')]);} public function table(Table $t):Table{return $t->columns([TextColumn::make('date')->date('d/m/Y'),TextColumn::make('status')->badge(),TextColumn::make('note')])->headerActions([Actions\CreateAction::make()])->recordActions([Actions\EditAction::make(),Actions\DeleteAction::make()]);}}
